class Solution {
public:
    int minSwaps(string s) {
        int n = s.size();
        int zeros = 0, ones = 0;
        for (char c : s) {
            if (c == '0') zeros++;
            else ones++;
        }

        int ans = n + 1;

        // Pattern starting with '0': "0101..."
        if (zeros == (n + 1) / 2 && ones == n / 2) {
            int mismatches = 0;
            for (int i = 0; i < n; i++) {
                if (s[i] != ((i % 2 == 0) ? '0' : '1'))
                    mismatches++;
            }
            ans = min(ans, mismatches / 2);
        }

        // Pattern starting with '1': "1010..."
        if (zeros == n / 2 && ones == (n + 1) / 2) {
            int mismatches = 0;
            for (int i = 0; i < n; i++) {
                if (s[i] != ((i % 2 == 0) ? '1' : '0'))
                    mismatches++;
            }
            ans = min(ans, mismatches / 2);
        }

        return (ans > n) ? -1 : ans;
    }
};
